window.MGProseData("ff07e68c7ea0049d39228a69a9c4e5885cda69094f846a0244e3bd3331078578",{"html":"\u003cp>记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ne_k(y)=e^{2\\pi i k\\cdot y},\\qquad d_k(\\alpha)=\\alpha k_1+k_2 .\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nN_\\alpha e_k=2\\pi i\\,d_k(\\alpha)e_k.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无理，对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 总有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_k(\\alpha)\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch2>S1 有限频带上的逆\u003c/h2>\n\u003cp>对\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nF=\\sum_{0\u0026lt;|k|\\le N}\\widehat F(k)e_k\\in H_N,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext>  \u003c/mtext>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmo>:\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmtext>  \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\;\nN_\\alpha^{-1}F\n:=\\sum_{0\u0026lt;|k|\\le N}\n\\frac{\\widehat F(k)}{2\\pi i(\\alpha k_1+k_2)}e_k .\n\\;}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n直接计算得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha N_\\alpha^{-1}F=F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，同理 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha^{-1}N_\\alpha F=F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故这是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的逆。\u003c/p>\n\u003cp>令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\delta_{\\alpha,N}:=\\min_{0\u0026lt;|k|\\le N}|\\alpha k_1+k_2|\u0026gt;0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 范数下，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是对角乘子算子，其乘子模为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac1{2\\pi |d_k(\\alpha)|}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\\in\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，精确的算子范数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmtext>  \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\;\n\\|N_\\alpha^{-1}\\|_{H^r\\to H^r}\n=\\max_{0\u0026lt;|k|\\le N}\\frac1{2\\pi |\\alpha k_1+k_2|}\n=\\frac1{2\\pi\\delta_{\\alpha,N}} .\n\\;}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它特别与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无关。\u003c/p>\n\u003chr>\n\u003ch2>S2 有算术界的截断误差\u003c/h2>\n\u003cp>假设\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|d_k(\\alpha)|\\ge c\\langle k\\rangle^{-s}\n\\qquad(k\\ne0).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对光滑零均值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widehat u(0)=0,\\qquad\n\\widehat u(k)=\\frac{\\widehat F(k)}{2\\pi i d_k(\\alpha)}\n\\quad(k\\ne0).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由算术界，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|\\widehat u(k)|\n\\le (2\\pi c)^{-1}\\langle k\\rangle^s|\\widehat F(k)|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho\\in\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>ρ\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|u\\|_{H^\\rho}\\le (2\\pi c)^{-1}\\|F\\|_{H^{\\rho+s}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 光滑，其所有 Sobolev 范数均有限，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmo>⋂\u003c/mo>\u003cmi>ρ\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>ρ\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\\in\\bigcap_\\rho H^\\rho=C^\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。其 Fourier 级数给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u=F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 零均值。\u003c/p>\n\u003cp>令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;|k|\\le N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的截断，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_N=N_\\alpha^{-1}F_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 恰好是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的同一频带截断。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nu-u_N=\\sum_{|k|\u0026gt;N}\\widehat u(k)e_k.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\n\\|u-u_N\\|_{H^r}^2\n\u0026amp;=\\frac1{4\\pi^2}\\sum_{|k|\u0026gt;N}\n\\frac{\\langle k\\rangle^{2r}|\\widehat F(k)|^2}{|d_k(\\alpha)|^2}\\\\\n\u0026amp;\\le \\frac1{(2\\pi c)^2}\\sum_{|k|\u0026gt;N}\n\\langle k\\rangle^{2r+2s}|\\widehat F(k)|^2.\n\\end{aligned}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k|\u0026gt;N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k\\rangle^2\u0026gt;1+N^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\langle k\\rangle^{-2q}\\le (1+N^2)^{-q}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n代入即得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|u-u_N\\|_{H^r}^2\n\\le \\frac{(1+N^2)^{-q}}{(2\\pi c)^2}\n\\|F\\|_{H^{r+s+q}}^2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmtext>  \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\;\n\\|u-u_N\\|_{H^r}\n\\le (2\\pi c)^{-1}(1+N^2)^{-q/2}\n\\|F\\|_{H^{r+s+q}} .\n\\;}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch2>S3 固定频带内改变方向\u003c/h2>\n\u003cp>对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;|k|\\le N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，两个解的 Fourier 系数分别为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widehat u_\\alpha(k)=\\frac{\\widehat F(k)}{2\\pi i d_k(\\alpha)},\n\\qquad\n\\widehat u_\\beta(k)=\\frac{\\widehat F(k)}{2\\pi i d_k(\\beta)}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmfrac>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widehat u_\\alpha(k)-\\widehat u_\\beta(k)\n=\\frac{\\widehat F(k)}{2\\pi i}\n\\frac{d_k(\\beta)-d_k(\\alpha)}\n{d_k(\\alpha)d_k(\\beta)}\n=\\frac{\\widehat F(k)}{2\\pi i}\n\\frac{(\\beta-\\alpha)k_1}{d_k(\\alpha)d_k(\\beta)}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n利用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>δ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|d_k(\\alpha)|,|d_k(\\beta)|\\ge\\delta\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|k_1|\\le |k|\\le N,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmi>δ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|\\widehat u_\\alpha(k)-\\widehat u_\\beta(k)|\n\\le \\frac{|\\alpha-\\beta|N}{2\\pi\\delta^2}|\\widehat F(k)|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两边乘以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k\\rangle^{2r}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 并求和，即得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmi>δ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmtext>  \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\;\n\\|u_\\alpha-u_\\beta\\|_{H^r}\n\\le \\frac{|\\alpha-\\beta|N}{2\\pi\\delta^2}\n\\|F\\|_{H^r}.\n\\;}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch2>S4 整体对象与全部恢复目标\u003c/h2>\n\u003ch3>1. 一般分类\u003c/h3>\n\u003cp>引入算术条件 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D_{\\alpha,s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">∃\u003c/mi>\u003cmi>c\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> 使得\u003c/mtext>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmtext>(\u003c/mtext>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003cmtext>)\u003c/mtext>\u003c/mrow>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\exists c\u0026gt;0\\ \\text{使得}\\qquad\n|d_k(\\alpha)|\\ge c\\langle k\\rangle^{-s}\n\\quad(k\\ne0). \\tag{\\(D_{\\alpha,s}\\)}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>\u003cstrong>定理。\u003c/strong> 对无理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/p>\n\u003col>\n\u003cli>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha:C_0^\\infty(\\mathbb T^2)\\to C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 总是单射。\u003c/li>\n\u003cli>它是双射，当且仅当存在某个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D_{\\alpha,s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立。\u003c/li>\n\u003cli>对固定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，估计\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|u\\|_{H^r}\\le C_{\\alpha,r,s}\\|N_\\alpha u\\|_{H^{r+s}}\n\\quad(u\\in C_0^\\infty)\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\\in\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立，当且仅当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D_{\\alpha,s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立。\u003c/li>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D_{\\alpha,s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 以常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立，则可以统一取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC_{\\alpha,r,s}=(2\\pi c)^{-1},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它甚至不依赖于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ol>\n\u003cp>因此，全部允许的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 恰好是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmtext> 成立\u003c/mtext>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext>  \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\;\n\\mathcal A_\\alpha:=\\{s\\ge0:D_{\\alpha,s}\\text{ 成立}\\},\n\\;}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n该集合为空或向上封闭。\u003c/p>\n\u003cp>\u003cstrong>证明。\u003c/strong>\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2\\pi i d_k(\\alpha)\\widehat u(k)=0,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat u(k)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；零均值条件又给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat u(0)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，单射性成立。相同计算也说明：只要光滑零均值解存在，它就必然唯一。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D_{\\alpha,s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立，则 S2 中的构造对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\\in C_0^\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 给出光滑零均值解，故算子为双射。同时\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|\\widehat u(k)|\n\\le (2\\pi c)^{-1}\\langle k\\rangle^s\n|\\widehat{N_\\alpha u}(k)|,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|u\\|_{H^r}\\le (2\\pi c)^{-1}\\|N_\\alpha u\\|_{H^{r+s}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>反过来，若固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 Sobolev 估计成立，取单频函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u=e_k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|e_k\\|_{H^r}=\\langle k\\rangle^r,\\qquad\n\\|N_\\alpha e_k\\|_{H^{r+s}}\n=2\\pi |d_k(\\alpha)|\\langle k\\rangle^{r+s},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n估计给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|d_k(\\alpha)|\n\\ge (2\\pi C_{\\alpha,r,s})^{-1}\\langle k\\rangle^{-s}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这正是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D_{\\alpha,s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>最后证明：若所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D_{\\alpha,s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都失败，则算子不是满射。此时对每个整数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c=1,s=n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可找到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\ell_n\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|d_{\\ell_n}(\\alpha)|\u0026lt;\\langle\\ell_n\\rangle^{-n}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这些 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\ell_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不可能全部落在有限频率集内，因为任何有限频率集上的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|d_k(\\alpha)|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有正下界，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle\\ell_n\\rangle^{-n}\\to0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。故可抽取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmo>⋯\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_1\u0026lt;n_2\u0026lt;\\cdots\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nk_j:=\\ell_{n_j}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两两不同，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_j\\ge j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|d_{k_j}(\\alpha)|\n\u0026lt;\\langle k_j\\rangle^{-n_j}\n\\le \\langle k_j\\rangle^{-j}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n现在一次性构造\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>:\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nF:=\\sum_{j=1}^\\infty 2\\pi i d_{k_j}(\\alpha)e_{k_j}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 足够大使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2n_j-2r\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\langle k_j\\rangle^{2r}\n|2\\pi i d_{k_j}(\\alpha)|^2\n\\le4\\pi^2\\langle k_j\\rangle^{2r-2n_j}\n\\le4\\pi^2\\langle k_j\\rangle^{-3}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 两两不同且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sum_{k\\in\\mathbb Z^2}\\langle k\\rangle^{-3}\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可知 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\\in H^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\\in C_0^\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>但若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u=F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有光滑解，则必须有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widehat u(k_j)\n=\\frac{2\\pi i d_{k_j}(\\alpha)}\n{2\\pi i d_{k_j}(\\alpha)}=1\n\\qquad(j\\ge1).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这给出无穷多个模为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的不同 Fourier 系数，与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\\in L^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 矛盾。因此该 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 没有光滑零均值解。证毕。\u003c/p>\n\u003ch3>2. \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_*=\\sqrt2-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的最小损失\u003c/h3>\n\u003cp>结论是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\mathcal A_{\\alpha_*}=[1,\\infty).}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以最小损失为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\boxed{s=1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmtext>可以取到\u003c/mtext>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\boxed{\\text{可以取到}}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>先证明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的算术界。写 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k=(m,n)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nd=(\\sqrt2-1)m+n=\\sqrt2m+n-m.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取共轭代数数\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>d\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmi>m\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde d=-(\\sqrt2+1)m+n=n-m-\\sqrt2m.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmover accent=\"true\">\u003cmi>d\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmi>m\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nd\\widetilde d=(n-m)^2-2m^2\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n是非零整数，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>d\u003c/mi>\u003cmover accent=\"true\">\u003cmi>d\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|d\\widetilde d|\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。另一方面，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>d\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>n\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>m\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|\\widetilde d|\n\\le |n|+(1+\\sqrt2)|m|\n\\le(2+\\sqrt2)\\langle k\\rangle.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>d\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|d|\\ge\\frac1{(2+\\sqrt2)\\langle k\\rangle}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m=0,n\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>d\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>n\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|d|=|n|\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，同一估计显然也成立。故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mrow>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmtext>  \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\;\n|\\alpha_*k_1+k_2|\n\\ge \\frac1{2+\\sqrt2}\\langle k\\rangle^{-1}\n\\qquad(k\\ne0).\n\\;}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n特别地，对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可以取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|u\\|_{H^r}\n\\le \\frac{2+\\sqrt2}{2\\pi}\\|N_{\\alpha_*}u\\|_{H^{r+1}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>再排除 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。Dirichlet 逼近定理适用于无理数，给出无穷多 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(p_j,q_j)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_j\\to\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|q_j\\alpha_*-p_j|\u0026lt;\\frac1{q_j}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_j=(q_j,-p_j)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p_j/q_j\\to\\alpha_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，存在固定常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k_j\\rangle\\le Aq_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若某个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的算术界以常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>c\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>c\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmsup>\u003cmi>A\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nc\u0026#x27;A^{-s}q_j^{-s}\n\\le |q_j\\alpha_*-p_j|\n\u0026lt;q_j^{-1},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n即\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo>\u0026lt;\u003c/mo>\u003cmfrac>\u003cmsup>\u003cmi>A\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmsup>\u003cmi>c\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq_j^{1-s}\u0026lt;\\frac{A^s}{c\u0026#x27;}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_j\\to\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1-s\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 矛盾。因此不允许任何 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch3>3. \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C^m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 恢复估计\u003c/h3>\n\u003cp>答案是肯定的。\u003c/p>\n\u003cp>维数为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，Sobolev 嵌入给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>v\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>v\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|v\\|_{C^m}\\le C_m\\|v\\|_{H^{m+2}},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m+2\u0026gt;m+2/2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。用 Fourier 系数和 Cauchy–Schwarz 也可直接看到这一点，关键在于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sum_{k\\in\\mathbb Z^2}\\langle k\\rangle^{-4}\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u=N_{\\alpha_*}^{-1}F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，利用已经取到的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 估计：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|u\\|_{H^{m+2}}\n\\le C\\|F\\|_{H^{m+3}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n另一方面，对整数阶 Sobolev 范数，展开 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(1+|k|^2)^{m+3}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 并使用 Parseval，可得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|F\\|_{H^{m+3}}\n\\le C_m\\|F\\|_{C^{m+3}}\n\\le C_m\\|F\\|_{C^{m+4}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n合并得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext>  \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\;\n\\|N_{\\alpha_*}^{-1}F\\|_{C^m}\n\\le C_m\\|F\\|_{C^{m+4}},\n\\;}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有限且与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无关。\u003c/p>\n\u003chr>\n\u003ch2>S5 邻近方向的一致估计\u003c/h2>\n\u003cp>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext>不存在这样的 \u003c/mtext>\u003cmi>J\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\text{不存在这样的 }J,s,C.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>反设存在。开区间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 内取一个有理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p/q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并固定非零频率\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nk=(q,-p).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对任意无理 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\\in J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，将所设估计用于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u=e_k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|e_k\\|_{L^2}=1,\\qquad\nN_\\alpha e_k=2\\pi i(\\alpha q-p)e_k,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n必须有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>C\u003c/mi>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmi>p\u003c/mi>\u003cmi>q\u003c/mi>\u003c/mfrac>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n1\\le 2\\pi C|\\alpha q-p|\\langle k\\rangle^s\n=2\\pi Cq\\left|\\alpha-\\frac pq\\right|\\langle k\\rangle^s.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n但无理数在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 内稠密，可令无理 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\\in J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 任意接近 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p/q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使右端任意小，矛盾。因此即使在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 本身有固定损失估计，也不存在对其整个邻域一致的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s,C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003chr>\n\u003ch2>S6 一个具体方向的不可解数据\u003c/h2>\n\u003cp>令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq_n=10^{n!},\\qquad\np_n=\\sum_{j=1}^n10^{n!-j!}\\in\\mathbb Z,\\qquad\nA_n=\\frac{p_n}{q_n}=\\sum_{j=1}^n10^{-j!}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n尾部满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;\\alpha-A_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>⋅\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\n\\alpha-A_n\n\u0026amp;=\\sum_{j=n+1}^\\infty10^{-j!}\\\\\n\u0026amp;\\le10^{-(n+1)!}\\sum_{\\ell=0}^\\infty10^{-\\ell}\n=\\frac{10}{9}10^{-(n+1)!}\n\u0026lt;2\\cdot10^{-(n+1)!}. \\tag{1}\n\\end{aligned}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch3>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的无理性\u003c/h3>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha=a/b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\\in\\mathbb Z,b\\in\\mathbb N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则因 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\\ne A_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，整数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">aq_n-bp_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非零，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>a\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\alpha-A_n\n=\\frac{|aq_n-bp_n|}{bq_n}\n\\ge\\frac1{bq_n}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n结合 (1) 得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>b\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>b\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n1\\le bq_n(\\alpha-A_n)\n\u0026lt;2b\\,10^{n!-(n+1)!}\n=2b\\,10^{-n\\,n!}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n右端随 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\\to\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 趋于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，矛盾。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无理。\u003c/p>\n\u003ch3>同一个光滑数据的构造\u003c/h3>\n\u003cp>定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nd_n:=\\alpha q_n-p_n=q_n(\\alpha-A_n)\u0026gt;0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 (1)，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>⋅\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(2)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n0\u0026lt;d_n\u0026lt;2q_n10^{-(n+1)!}\n=2\\cdot10^{-n\\,n!}. \\tag{2}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取频率\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nk_n=(q_n,-p_n).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 严格递增，这些频率两两不同。又 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;A_n\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;p_n\u0026lt;q_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，从而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003c/msqrt>\u003cmo>≤\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>⋅\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(3)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\langle k_n\\rangle\n=\\sqrt{1+q_n^2+p_n^2}\n\\le2q_n=2\\cdot10^{n!}. \\tag{3}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>现在构造单个函数\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext>  \u003c/mtext>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmtext>  \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\;\nF(y):=\\sum_{n=1}^\\infty\n2\\pi i d_n\\,e^{2\\pi i(q_ny_1-p_ny_2)} .\n\\;}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它没有零频项，所以只要光滑便自动零均值。\u003c/p>\n\u003cp>验证其光滑性：对任意固定整数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由 (2)、(3)，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003cmi>π\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi>π\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi>π\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\n\\langle k_n\\rangle^M|2\\pi i d_n|\n\u0026amp;\\le4\\pi\\,\\langle k_n\\rangle^M10^{-n n!}\\\\\n\u0026amp;\\le2^{M+2}\\pi\\,10^{M n!}10^{-n n!}\\\\\n\u0026amp;=2^{M+2}\\pi\\,10^{-(n-M)n!}.\n\\end{aligned}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对每个固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>n\u003c/mi>\u003c/munder>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\sum_n10^{-(n-M)n!}\u0026lt;\\infty,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u0026lt;M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 只有有限项，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\\ge M+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(n-M)n!\\ge n!\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此所有阶导数的形式级数都绝对且一致收敛，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>最后，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u=F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有光滑零均值解，则 Fourier 系数必须满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2\\pi i(\\alpha q_n-p_n)\\widehat u(k_n)\n=2\\pi i d_n.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_n\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，这迫使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace width=\"2em\"/>\u003cmtext>对所有 \u003c/mtext>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widehat u(k_n)=1\\qquad\\text{对所有 }n\\ge1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n于是 Parseval 给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>≥\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmn>1\u003c/mn>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|u\\|_{L^2}^2\n\\ge\\sum_{n=1}^\\infty|\\widehat u(k_n)|^2\n=\\sum_{n=1}^\\infty1=\\infty,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\\in L^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 矛盾。因此上述\u003cstrong>同一个光滑零均值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong> 没有光滑零均值解。\u003c/p>\n","source":"assets/content/ff07e68c7ea0049d39228a69a9c4e5885cda69094f846a0244e3bd3331078578.html"});
